def transform(grid):
    h,w=len(grid),len(grid[0])
    if 1 in grid[0]:
        n=grid[0].count(1)+1
        end=grid[0].index(1)
        while end>0 and grid[0][end-1]==0: end-=1
        return [sum(([0]+row[:end] for _ in range(n-1)),row[:end]) for row in grid]
    n=sum(row[0]==1 for row in grid)+1
    end=next((r for r in range(h) if grid[r][0]==1),h)
    while end>0 and all(v==0 for v in grid[end-1]): end-=1
    out=[]
    for k in range(n):
        if k: out.append([0]*w)
        out.extend(row[:] for row in grid[:end])
    return out

